# orbit: app-dev app-instance-3009
https://conntweak1.ihj-proof-h42.test {
    bind 10.44.0.7 192.168.6.20
    @orbit_task_vms remote_ip 10.44.0.128/25
    abort @orbit_task_vms
    tls /etc/caddy/orbit-certificates/app-instance-3009/current/cert.pem /etc/caddy/orbit-certificates/app-instance-3009/current/key.pem
    @orbit_probe header X-Orbit-Probe 1
log_skip @orbit_probe
log_skip @orbit_asleep
log {
    output file /data/caddy/orbit/hibernation/app-instance-3009.log {
        roll_size 1MiB
        roll_keep 1
    }
}
@orbit_asleep {
    not header X-Orbit-Probe 1
    file {
        root /data/caddy/orbit/hibernation
        try_files /app-instance-3009.asleep
    }
}
handle @orbit_asleep {
    forward_auth https://gateway.orbit {
        uri /api/v1/runtime-activations/app-instance/3009
        header_up Host gateway.orbit
        transport http {
            tls_trusted_ca_certs /usr/local/share/ca-certificates/orbit-managed-root-ca.crt
            tls_server_name gateway.orbit
        }
    }
}
    @orbit_vite {
    path /__orbit/vite /__orbit/vite/*
}
handle @orbit_vite {
    reverse_proxy 10.253.0.82:5173
}
handle {
    reverse_proxy 10.253.0.82:8080 {
    flush_interval -1
    transport http {
        read_timeout 1h
        response_header_timeout 1h
    }
}
}
}

